<canvas id="canvas"></canvas><div class="hud">DIGITS <b id="h-i">0</b><br>MODE <b id="h-mode">WALK</b><br>SPEED <b id="h-speed">4</b><br><span class="sub">PI</span> <b>3.14159</b></div><?php $interactionHints=[['type'=>'click','label'=>'restart'],['type'=>'drag','label'=>'steer']];require_once __DIR__ . '/includes/interaction-hints.php';?>
<div id="controls" class="drawer-controls"><div><div class="btn-row"><button class="control-btn active" data-mode="walk">WALK</button><button class="control-btn" data-mode="spiral">SPIRAL</button><button class="control-btn" data-mode="chord">CHORD</button></div></div><div><div class="slider-row"><span class="slider-label">SPEED</span><input type="range" id="sl-speed" min="1" max="18" value="4"><span class="slider-value" id="sv-speed">4</span></div></div><div><div class="slider-row"><span class="slider-label">STEP</span><input type="range" id="sl-step" min="3" max="18" value="9"><span class="slider-value" id="sv-step">9</span></div></div><div><div class="btn-row"><button class="control-btn active" id="btn-run">RUN</button><button class="control-btn" id="btn-reset">RESET</button></div></div></div><?php require_once __DIR__ . '/includes/drawer-controls.php';?>
<script>(function(){var c=document.getElementById('canvas'),x=c.getContext('2d'),W,H,D=1,mode='walk',speed=4,step=9,run=true,idx=0,px=0,py=0,ang=0,pts=[];var digits='';var hi=document.getElementById('h-i'),hm=document.getElementById('h-mode'),hs=document.getElementById('h-speed'),ss=document.getElementById('sl-speed'),st=document.getElementById('sl-step'),vs=document.getElementById('sv-speed'),vt=document.getElementById('sv-step');function resize(){D=Math.min(2,devicePixelRatio||1);W=c.width=Math.floor(innerWidth*D);H=c.height=Math.floor(innerHeight*D);c.style.width=innerWidth+'px';c.style.height=innerHeight+'px';reset()}function reset(){idx=0;px=W/2;py=H/2;ang=0;pts=[];x.fillStyle='#0a0a0f';x.fillRect(0,0,W,H)}function digit(){var d=+digits[idx++%digits.length];hi.textContent=idx;return d}function iter(){var d=digit();if(mode==='walk'){ang+=(d-4.5)*.25;px+=Math.cos(ang)*step*D;py+=Math.sin(ang)*step*D;if(px<0||px>W||py<0||py>H){px=W/2;py=H/2}pts.push({x:px,y:py,d:d})}else if(mode==='spiral'){var a=idx*.18+d*.05,r=Math.min(W,H)*.00042*idx;pts.push({x:W/2+Math.cos(a)*r,y:H/2+Math.sin(a)*r,d:d})}else{var a1=d/10*Math.PI*2,a2=((+digits[idx%digits.length])/10)*Math.PI*2,r=Math.min(W,H)*.36;pts.push({x:W/2+Math.cos(a1)*r,y:H/2+Math.sin(a1)*r,x2:W/2+Math.cos(a2)*r,y2:H/2+Math.sin(a2)*r,d:d})}pts=pts.slice(-1400)}function draw(){if(run)for(var i=0;i<speed;i++)iter();x.fillStyle='rgba(10,10,15,.16)';x.fillRect(0,0,W,H);x.globalCompositeOperation='lighter';for(var i=1;i<pts.length;i++){var p=pts[i],q=pts[i-1],a=i/pts.length;x.strokeStyle=p.d%2?'rgba(0,245,212,'+(.08+a*.62)+')':'rgba(123,44,191,'+(.08+a*.52)+')';x.lineWidth=(.7+a*1.8)*D;x.beginPath();if(mode==='chord'){x.moveTo(p.x,p.y);x.lineTo(p.x2,p.y2)}else{x.moveTo(q.x,q.y);x.lineTo(p.x,p.y)}x.stroke()}x.globalCompositeOperation='source-over';requestAnimationFrame(draw)}function hud(){hm.textContent=mode.toUpperCase();hs.textContent=speed;vs.textContent=speed;vt.textContent=step}c.onclick=()=>{reset();if(typeof SFX!=='undefined')SFX.play('success')};c.onpointermove=e=>{if(e.buttons){ang+=(e.movementX||0)*.01;if(typeof SFX!=='undefined')SFX.play('move',120)}};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;reset();document.querySelectorAll('[data-mode]').forEach(q=>q.classList.toggle('active',q===b));hud();if(typeof SFX!=='undefined')SFX.play('toggle')});ss.oninput=()=>{speed=+ss.value;hud()};st.oninput=()=>{step=+st.value;hud()};document.getElementById('btn-run').onclick=e=>{run=!run;e.currentTarget.classList.toggle('active',run);if(typeof SFX!=='undefined')SFX.play('toggle')};document.getElementById('btn-reset').onclick=()=>{reset();if(typeof SFX!=='undefined')SFX.play('success')};addEventListener('resize',resize);resize();hud();draw()})();</script><?php require_once __DIR__ . '/includes/sfx.php';require_once __DIR__ . '/includes/page-end.php';?></body></html>